A blockchain is a distributed database that stores data in a decentralized manner, while a conventional database stores data in a centralized manner. In a blockchain, data is stored in blocks that are linked together in a chain, with each block containing a cryptographic hash of the previous block, which ensures the integrity of the data. The decentralized nature of blockchain means that there is no central authority controlling the data, and transactions are validated by a network of nodes rather than a single entity.
In contrast, a conventional database stores data in a centralized location, and transactions are validated by a single authority or a group of authorities. This makes conventional databases more vulnerable to security breaches and data manipulation, as there is a single point of failure.
Here's an example C++ program that demonstrates the concept of blockchain:
```
#include <iostream>
#include <string>
#include <vector>
#include <ctime>
#include <sstream>
#include <iomanip>
using namespace std;
// Block class
class Block {
    private:
        int index;
        string data;
        string timestamp;
        string hash;
        string previousHash;
        int nonce;
        string calculateHash() const {
            stringstream ss;
            ss << index << data << timestamp << previousHash << nonce;
            return sha256(ss.str());
        }
    public:
        Block(int index, const string& data, const string& previousHash): index(index), data(data), previousHash(previousHash) {
            timestamp = getCurrentTime();
            nonce = 0;
            hash = calculateHash();
        }
        int getIndex() const {
            return index;
        }
        string getData() const {
            return data;
        }
        string getTimestamp() const {
            return timestamp;
        }
        string getHash() const {
            return hash;
        }
        string getPreviousHash() const {
            return previousHash;
        }
        void mineBlock(int difficulty) {
            string target(difficulty, '0');
            while (hash.substr(0, difficulty) != target) {
                nonce++;
                hash = calculateHash();
            }
            cout << "Block mined: " << hash << endl;
        }
    private:
        string getCurrentTime() const {
            time_t now = time(nullptr);
            tm localTime = *localtime(&now);
            stringstream ss;
            ss << put_time(&localTime, "%d-%m-%Y %H:%M:%S");
            return ss.str();
        }
        string sha256(const string& input) const {
            // SHA-256 implementation
            return "";
        }
};
// Blockchain class
class Blockchain {
    private:
        vector<Block> chain;
        int difficulty;
    public:
        Blockchain(int difficulty): difficulty(difficulty) {
            chain.emplace_back(0, "Genesis Block", "");
        }
        void addBlock(const string& data) {
            chain.emplace_back(chain.size(), data, chain.back().getHash());
            chain.back().mineBlock(difficulty);
        }
        bool isChainValid() const {
            for (int i = 1; i < chain.size(); i++) {
                const Block& currentBlock = chain[i];
                const Block& previousBlock = chain[i - 1];
                if (currentBlock.getHash() != currentBlock.calculateHash()) {
                    return false;
                }
                if (currentBlock.getPreviousHash() != previousBlock.getHash()) {
                    return false;
                }
            }
            return true;
        }
        void printChain() const {
            for (const Block& block : chain) {
                cout << "Index: " << block.getIndex() << endl;
                cout << "Data: " << block.getData() << endl;
                cout << "Timestamp: " << block.getTimestamp() << endl;
                cout << "Hash: " << block.getHash() << endl;
                cout << "Previous Hash: " << block.getPreviousHash() << endl;
                cout << endl;
            }
        }
};
// Main function
int main() {
    Blockchain blockchain(4);
    blockchain.addBlock("Transaction 1");
    blockchain.addBlock("Transaction 2");
    blockchain.addBlock("Transaction 3");
    blockchain.printChain();
    cout << "Is chain valid? " << (blockchain.isChainValid() ? "Yes" : "No") << endl;
    return 0;
}
```
This program implements a simple blockchain in C++. The `Block` class represents a block in the blockchain, with each block containing an index, data, timestamp, hash, previous hash, and nonce. The `Blockchain` class represents the blockchain itself, with each block being added to the chain using the `addBlock` method. The `isChainValid` method checks if the blockchain is valid by verifying the integrity of each block and the chain as a whole. The `printChain` method prints out the entire blockchain.
Note that the `sha256` method is not implemented in this program, as it is beyond the scope of this example. However, this method would be responsible for calculating the SHA-256 hash of a given input string.

