import random
def arithmetic_operation(numbers, operation):
    if not isinstance(numbers, list) or not all(isinstance(n, int) for n in numbers):
        raise ValueError("Invalid input: the first argument must be a list of integers")
    if not isinstance(operation, str) or operation not in ["+", "-", "*", "/", "**"]:
        raise ValueError("Invalid input: the second argument must be a string representing an arithmetic operation (+, -, *, /, or **)")
    if operation == "+":
        return sum(numbers)
    elif operation == "-":
        return numbers[0] - sum(numbers[1:])
    elif operation == "*":
        result = 1
        for n in numbers:
            result *= n
        return result
    elif operation == "/":
        result = numbers[0]
        for n in numbers[1:]:
            if n == 0:
                raise ZeroDivisionError("Cannot divide by zero")
            result /= n
        return result
    elif operation == "**":
        return numbers[0] ** numbers[1]
```
