% Perform numerical integration using Euler's method
for i = 1:nsteps
    % Compute gravitational forces
    F12 = F(r(i,:,1), r(i,:,2), m1, m2);
    F21 = -F(r(i,:,1), r(i,:,2), m1, m2);

    % Update position and velocity using Euler's method
    r(i+1,:,1) = r(i,:,1) + v(i,:,1)*dt;
    r(i+1,:,2) = r(i,:,2) + v(i,:,2)*dt;
    v(i+1,:,1) = v(i,:,1) + F12/m1*dt;
    v(i+1,:,2) = v(i,:,2) + F21/m2*dt;
end
% Plot orbits
