r12norm = vecnorm(r12, 2, 2);
v12 = v(:,:,2) - v(:,:,1);
v12norm = vecnorm(v12, 2, 2);
E = 0.5*m1*vecnorm(v(:,:,1), 2, 2).^2 + 0.5*m2*vecnorm(v(:,:,2), 2, 2).^2 - G*m1*m2./r12norm;
figure;
