plot(t, r12norm);
ylabel('Distance (m)');
subplot(3,1,2);
plot(t, v12norm);
ylabel('Relative velocity (m/s)');
subplot(3,1,3);
plot(t, E);
ylabel('Total energy (J)');
xlabel('Time (s)');
% Calculate and display eccentricity and semi-major axis
h = cross(r12, v12);
hmag = vecnorm(h, 2, 2);
emag = sqrt(1 - hmag.^2./(G*(m1+m2)*r12norm));
a = -G*(m1+m2)./(2*E);
