import edu.stanford.nlp.semgraph.SemanticGraphCoreAnnotations;
import edu.stanford.nlp.sentiment.SentimentCoreAnnotations;
import edu.stanford.nlp.trees.Tree;
import edu.stanford.nlp.trees.TreeCoreAnnotations;
import edu.stanford.nlp.util.CoreMap;
import java.util.Properties;
public class NLPExample {
    public static void main(String[] args) {
        // Set up the Stanford CoreNLP pipeline
        Properties props = new Properties();
        props.setProperty("annotators", "tokenize, ssplit, pos, parse, sentiment");
        StanfordCoreNLP pipeline = new StanfordCoreNLP(props);
        // Define the input sentence
        String sentence = "Public transport has been disrupted due to the pandemic";
        // Create an Annotation object
        Annotation annotation = new Annotation(sentence);
        // Run the pipeline on the input sentence
        pipeline.annotate(annotation);
        // Extract the relevant annotations from the pipeline output
        CoreMap sentenceMap = annotation.get(CoreAnnotations.SentencesAnnotation.class).get(0);
        Tree tree = sentenceMap.get(TreeCoreAnnotations.TreeAnnotation.class);
        SemanticGraph dependencies = sentenceMap.get(SemanticGraphCoreAnnotations.CollapsedCCProcessedDependenciesAnnotation.class);
        String sentiment = sentenceMap.get(SentimentCoreAnnotations.SentimentClass.class);
        // Print out the part-of-speech tags for each word in the sentence
        System.out.println("Part-of-speech tags:");
        for (CoreLabel token : sentenceMap.get(CoreAnnotations.TokensAnnotation.class)) {
            String word = token.get(CoreAnnotations.TextAnnotation.class);
            String pos = token.get(CoreAnnotations.PartOfSpeechAnnotation.class);
            System.out.println(word + " - " + pos);
        }
        // Print out the syntactic parse tree for the sentence
        System.out.println("Syntactic parse tree:");
        System.out.println(tree);
        // Print out the dependencies between words in the sentence
        System.out.println("Dependencies:");
        System.out.println(dependencies);
        // Print out the sentiment of the sentence
        System.out.println("Sentiment:");
        System.out.println(sentiment);
    }
}
```
