using System;
class Program {
    static void Main(string[] args) {
        string message = "Hello, world!"; // Change this to your message
        string encryptedMessage = EncryptMessage(message);
        Console.WriteLine(encryptedMessage);
    }
    static string EncryptMessage(string message) {
        // Remove all spaces and punctuation
        string cleanedMessage = new string(message.ToLower().Where(c => char.IsLetter(c)).ToArray());
        // Group the letters into pairs
        string pairedMessage = "";
        for (int i = 0; i < cleanedMessage.Length; i += 2) {
            if (i + 1 < cleanedMessage.Length) {
                pairedMessage += cleanedMessage[i + 1].ToString() + cleanedMessage[i].ToString();
            } else {
                pairedMessage += cleanedMessage[i].ToString();
            }
        }
        // Reverse the order of the pairs
        char[] reversedPairs = pairedMessage.ToCharArray();
        Array.Reverse(reversedPairs);
        string reversedPairedMessage = new string(reversedPairs);
        // Reverse the order of the letters in each word
        string[] words = reversedPairedMessage.Split(' ');
        for (int i = 0; i < words.Length; i++) {
            char[] letters = words[i].ToCharArray();
            Array.Reverse(letters);
            words[i] = new string(letters);
        }
        // Join the words back together
        string encryptedMessage = string.Join(" ", words);
        // Preserve the case of the letters
        char[] originalLetters = message.ToCharArray();
        char[] encryptedLetters = encryptedMessage.ToCharArray();
        for (int i = 0; i < originalLetters.Length; i++) {
            if (char.IsUpper(originalLetters[i])) {
                encryptedLetters[i] = char.ToUpper(encryptedLetters[i]);
            }
        }
        return new string(encryptedLetters);
    }
}
```
