```go
package main
import (
    "bytes"
    "fmt"
    "regexp"
)
func main() {
    htmlString := "<div><p>Hello, <b>world!</b></p></div>"
    fmt.Println("Original HTML string:", htmlString)
    // Remove unnecessary HTML tags
    cleanedString := removeHTMLTags(htmlString)
    fmt.Println("Cleaned HTML string:", cleanedString)
    // Add random HTML tags
    modifiedString := addHTMLTags(cleanedString)
    fmt.Println("Modified HTML string:", modifiedString)
}
func removeHTMLTags(htmlString string) string {
    // Remove all HTML tags except <span>
    re := regexp.MustCompile(`<(?:(?!span)[^>])+>`)
    cleanedString := re.ReplaceAllString(htmlString, "")
    return cleanedString
}
func addHTMLTags(htmlString string) string {
    // Add a <span> tag with no attributes
    modifiedString := bytes.ReplaceAll([]byte(htmlString), []byte("world"), []byte("<span>Hello, world!</span>"))
    return string(modifiedString)
}
```
In this code, the `removeHTMLTags` function uses a regular expression to remove all HTML tags except the `<span>` tag. The `addHTMLTags` function adds a `<span>` tag with no attributes around the word "world" in the HTML string.
Note that this code is not foolproof and may not work correctly for all HTML strings. It's always a good idea to test your code with various inputs to ensure that it works as expected.

