<?php
// Function to calculate the distance between two users based on their location data
function calculateDistance($user1_lat, $user1_lng, $user2_lat, $user2_lng) {
  $earth_radius = 6371; // Radius of the earth in km
  $dLat = deg2rad($user2_lat - $user1_lat);
  $dLon = deg2rad($user2_lng - $user1_lng);
  $a = sin($dLat/2) * sin($dLat/2) + cos(deg2rad($user1_lat)) * cos(deg2rad($user2_lat)) * sin($dLon/2) * sin($dLon/2);
  $c = 2 * atan2(sqrt($a), sqrt(1-$a));
  $distance = $earth_radius * $c; // Distance in km
  return $distance;
}
// Function to update the user's status on a website dashboard according to their potential exposure to the virus
